css:
#bg { position:absolute; inset:-40px; width:2000px; height:1160px; object-fit:cover; filter:blur(22px) brightness(.38); }
#top { position:absolute; top:70px; left:0; right:0; text-align:center; }
#thanks { font-weight:700; font-size:76px; letter-spacing:.04em; }
#rule { width:260px; height:8px; background:var(--red); margin:22px auto 0; transform-origin:center; }
#bottom { position:absolute; bottom:64px; left:0; right:0; text-align:center; font-weight:400; font-size:38px; }
#bottom b { color:#fff; background:var(--red); font-weight:700; padding:2px 14px; }

js:
const b = document.getElementById('bottom');
b.append('Subscribe to ');
const n = document.createElement('b'); n.textContent = V.channel; b.appendChild(n);
b.append(' for more trailer breakdowns');
const D = V.duration;
tl.fromTo('#bg', { scale: 1.0 }, { scale: 1.08, duration: D, ease: 'none' }, 0);
tl.fromTo('#thanks', { y: -40, opacity: 0 }, { y: 0, opacity: 1, duration: 0.6, ease: 'power3.out' }, 0.2);
